tools.example:
add_block('simulink/Sinks/Scope', 'mdl/Scope', 'Position', [300 100 330 130]);
set_param('mdl/Scope', 'NumInputPorts', '2');
cfg = get_param('mdl/Scope', 'ScopeConfiguration');
cfg.LayoutDimensions = [2 1];
cfg.OpenAtSimulationStart = true;

add_block('simulink/Sinks/Floating Scope', 'mdl/Probe', 'Position', [400 200 430 230]);
cfg = get_param('mdl/Probe', 'ScopeConfiguration');
cfg.OpenAtSimulationStart = true;
cfg.ShowLegend = true;

add_block('simulink/Sinks/To Workspace', 'mdl/Log');
set_param('mdl/Log', 'VariableName', 'y', 'SaveFormat', 'Timeseries', 'Decimation', '1');
out = sim('mdl');
plot(out.y.Time, out.y.Data);

add_block('simulink/Sinks/Out1', 'mdl/y', 'Port', '1', 'Position', [420 100 450 120]);
set_param('mdl/y', 'OutDataTypeStr', 'double', 'SignalName', 'speed');
out = sim('mdl');
plot(out.tout, out.yout{1}.Values.Data);

add_block('simulink/Sinks/Stop Simulation', 'mdl/Halt', 'Position', [420 320 450 340]);
add_block('simulink/Logic and Bit Operations/Compare To Constant', 'mdl/TooFast');
set_param('mdl/TooFast', 'relop', '>', 'const', '120');
add_line('mdl', 'TooFast/1', 'Halt/1');

add_block('simulink/Dashboard/Dashboard Scope', 'vdp/Dashboard Scope', 'Position', [420 60 620 200]);
sigSpec = Simulink.HMI.SignalSpecification;
sigSpec.BlockPath = Simulink.BlockPath('vdp/Mu');
sigSpec.OutputPortIndex = 1;
set_param('vdp/Dashboard Scope', 'Binding', {sigSpec});

load_system('vdp');
h = getSimulinkBlockHandle('vdp/Scope');
cfg = get_param(h, 'ScopeConfiguration');
cfg.NumInputPorts = '2';
cfg.LayoutDimensions = [2 1];
cfg.ActiveDisplay = 1;
cfg.YLimits = [-3 3];
cfg.DataLogging = true;
cfg.DataLoggingVariableName = 'scopeData';

add_block('dspsnks4/Time Scope', 'mdl/TScope');
cfg = get_param('mdl/TScope', 'ScopeConfiguration');
cfg.NumInputPorts = '2';
cfg.OpenAtSimulationStart = true;
cfg.TimeSpan = 0.05;

add_block('dspsnks4/Spectrum Analyzer', 'mdl/SA');
cfg = get_param('mdl/SA', 'ScopeConfiguration');
cfg.SampleRateSource = 'Property';
cfg.SampleRate = 44100;
cfg.SpectrumType = 'Power density';
cfg.PlotAsTwoSidedSpectrum = false;

add_block('dspsnks4/Array Plot', 'mdl/Spectrum');
cfg = get_param('mdl/Spectrum', 'ScopeConfiguration');
cfg.PlotType = 'Line';
cfg.YScale = 'Log';
cfg.ShowLegend = true;
